// Desktop-first session design. The desktop and every input are simulated.
(() => {
  function render(state, helpers) {
    const { icon, escape, sessionDevice, route, desktop } = helpers;
    const device = sessionDevice();
    const control = state.session === 'control';
    const button = (action, label, glyph, extra = '') => `<button data-action="${action}" class="remote-tool ${extra}" title="${label}" aria-label="${label}">${icon(glyph, 18)}<span>${label}</span></button>`;
    const activeTasks = (state.fileTransfers || []).filter(task => !['completed', 'cancelled', 'failed', 'stopped', 'skipped'].includes(task.status)).length;
    return `<div class="remote-session ${state.toolbarCollapsed ? 'bar-collapsed' : ''}" data-mode="${state.session}" data-fit="${state.screenFit}" data-quality="${state.quality}">
      <div class="desktop-stage">${desktop()}</div>
      <div class="remote-topbar" aria-label="远程会话工具栏">
        <div class="remote-identity">${button('session-back', '返回设备', 'left')}<div><strong>${escape(device.name)}</strong><small><i class="dot"></i>${state.activeAccess === 'unattended' ? '无人值守' : '临时协助'} · ${route()}</small></div></div>
        <div class="remote-mode-switch" aria-label="操作模式"><button data-action="view-mode" aria-pressed="${!control}" class="${control ? '' : 'selected'}">${icon('monitor', 14)}仅查看</button><button data-action="control-mode" aria-pressed="${control}" class="${control ? 'selected' : ''}">${icon('mouse', 14)}${state.controlRequested ? '等待允许' : '控制'}</button></div>
        <div class="remote-tool-group">${button('files', '文件', 'folder', state.filesOpen ? 'selected' : '')}${button('keyboard', '键盘', 'keyboard', state.keyboard ? 'selected' : '')}${button('tools', '工具', 'settings', state.tools ? 'selected' : '')}</div>
        <div class="remote-end-group">${button('disconnect', '断开', 'power', 'end')}${button('collapse-toolbar', '收起工具栏', 'chevron-up', 'collapse')}</div>
      </div>
      ${state.toolbarCollapsed ? `<button class="remote-handle" data-action="collapse-toolbar" aria-label="展开会话工具栏">${icon('monitor', 15)}${escape(device.name)}<span class="handle-mode">${control ? '控制中' : '仅查看'}</span>${icon('chevron-down', 13)}</button>` : ''}
      <div class="remote-mode-note">${icon(control ? 'mouse' : 'lock', 13)}${control ? '控制中 · 操作当前桌面' : state.controlGranted ? '仅查看 · 已暂停键盘与鼠标' : '仅查看 · 操作尚未授权'}</div>
      <div class="remote-connection-note">${icon('lock', 12)}已加密 <span>24 ms · 示例 · ${state.quality === 'balanced' ? '均衡' : state.quality === 'smooth' ? '流畅' : '清晰'}</span></div>
      ${state.event ? `<div class="remote-input-feedback" role="status">${escape(state.event)}</div>` : ''}
      ${state.tools ? `<aside class="remote-popover" aria-label="会话设置"><header><h3>会话工具</h3>${button('tools', '关闭工具', 'close')}</header><div class="remote-pop-body"><div class="remote-permission-summary"><span>${icon('shield', 19)}</span><div><strong>${state.controlGranted ? '已获得操作权限' : '当前仅允许查看'}</strong><p>${state.controlGranted ? '可随时切换仅查看，保留本次授权。' : '请求操作后，需要被控端单独允许。'}</p></div></div>${!state.controlGranted ? `<button class="btn soft block" data-action="${state.controlRequested ? 'cancel-control' : 'request-control'}">${state.controlRequested ? '取消操作请求' : '请求操作权限'}</button>` : ''}<label>输入方式</label><div class="mode-toggle"><button data-action="input-trackpad" class="${state.inputMode === 'trackpad' ? 'active' : ''}">鼠标 / 触控板</button><button data-action="input-touch" class="${state.inputMode === 'touch' ? 'active' : ''}">直接触控</button></div><button class="remote-option" data-action="trackpad">${icon('hand', 18)}${state.trackpad ? '收起' : '展开'}触控板 ${icon('right', 13)}</button><label>画面显示</label><div class="mode-toggle"><button class="${state.screenFit !== 'fill' ? 'active' : ''}" data-action="screen-fit">适应窗口</button><button class="${state.screenFit === 'fill' ? 'active' : ''}" data-action="screen-fill">填满画面</button></div><label for="quality">画面质量</label><select id="quality" aria-label="画面质量"><option value="balanced" ${state.quality === 'balanced' ? 'selected' : ''}>均衡 · 自动适应</option><option value="smooth" ${state.quality === 'smooth' ? 'selected' : ''}>流畅 · 节省流量</option><option value="clear" ${state.quality === 'clear' ? 'selected' : ''}>清晰 · 细节优先</option></select><div class="remote-pop-stats"><span>实际路径<strong>${route()}</strong></span><span>授权来源<strong>${state.activeAccess === 'unattended' ? '本机预设策略' : '本次现场批准'}</strong></span><span>文件权限<strong>${state.filePermissions.upload ? '可上传' : '上传关闭'} / ${state.filePermissions.download ? '可下载' : '下载关闭'}</strong></span></div></div></aside>` : ''}
      ${state.trackpad ? `<section class="remote-trackpad" aria-label="触控板面板"><header><span>${icon('hand', 15)}触控板</span>${button('trackpad', '关闭触控板', 'close')}</header><div class="touchpad ${control ? '' : 'locked'}" aria-label="模拟触控板"><span>${icon(control ? 'mouse' : 'lock', 22)}<br>${control ? '滑动移动光标 · 轻点单击' : '仅查看模式，操作已暂停'}</span></div><footer><button data-action="left-click" ${control ? '' : 'disabled'}>左键</button><button data-action="right-click" ${control ? '' : 'disabled'}>右键</button></footer></section>` : ''}
      ${state.keyboard ? `<section class="remote-keyboard input-dock" aria-label="远程键盘"><header><span>${icon('keyboard', 17)}输入到远端 <small id="remote-input-status">${helpers.keyboardActive() ? '直接输入，中文选词后自动提交' : '输入已暂停，点击键盘继续'}</small></span>${button('keyboard-close', '收起键盘', 'close')}</header><div class="remote-shortcuts">${[['Esc','Esc'],['Tab','Tab'],['Backspace','退格'],['Enter','回车'],['Ctrl + C','Ctrl + C'],['Ctrl + V','Ctrl + V']].map(([key,label]) => `<button data-action="key-${key}" ${control ? '' : 'disabled'}>${label}</button>`).join('')}</div></section>` : ''}
      ${activeTasks && !state.filesOpen ? `<button class="remote-transfer-pill" data-action="files">${icon('folder', 15)}文件任务 ${activeTasks} ${icon('right', 13)}</button>` : ''}
      ${state.filesOpen ? `<div class="file-overlay"><div class="file-window">${window.FilePrototype.render(state, helpers)}</div></div>` : ''}
    </div><div class="simulation-bar"><label>原型演示 · 模拟远端事件</label>${state.controlGranted ? '<button data-action="simulate-revoke">对方撤销操作</button>' : '<button data-action="simulate-grant">对方允许操作</button>'}<button data-action="simulate-network">网络中断</button><button data-action="role-host">查看被控端</button></div>`;
  }
  window.SessionPrototype = { render };
})();
